<?php
declare(strict_types=1);

require dirname(__DIR__).'/app/bootstrap.php';$user=require_role('admin');
$status=(string)($_GET['status']??'');$allowed=['pending','published','hidden'];$where='1=1';$params=[];if(in_array($status,$allowed,true)){$where='rv.status=?';$params[]=$status;}
$statement=db()->prepare("SELECT rv.*,c.full_name client_name,p.full_name provider_name,r.title request_title FROM reviews rv JOIN users c ON c.id=rv.client_id JOIN users p ON p.id=rv.provider_id JOIN service_requests r ON r.id=rv.request_id WHERE $where ORDER BY rv.created_at DESC LIMIT 200");$statement->execute($params);$rows=$statement->fetchAll();
$pageTitle='Reseñas';$pageSubtitle='Moderación de evaluaciones';$activeDashboard='reviews';require dirname(__DIR__).'/templates/dashboard-header.php';
?>
<div class="page-head"><div><h2>Reseñas</h2><p><?=count($rows)?> resultados mostrados</p></div></div><form class="filter-bar" method="get"><div class="field"><label for="status">Estado</label><select id="status" name="status" data-auto-submit><option value="">Todos</option><?php foreach($allowed as $option):?><option value="<?=e($option)?>"<?=selected($status,$option)?>><?=e(status_label($option))?></option><?php endforeach;?></select></div><div></div><button class="btn btn-secondary">Filtrar</button></form>
<section class="panel"><?php if($rows===[]):?><div class="empty-state"><span class="empty-icon"><?=icon('star')?></span><h3>No hay reseñas</h3><p>Las evaluaciones aparecerán cuando existan servicios completados.</p></div><?php else:?><div class="table-scroll"><table class="data-table"><thead><tr><th>Servicio</th><th>Participantes</th><th>Calificación</th><th>Comentario</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="table-title"><strong><?=e($row['request_title'])?></strong><span><?=e(date_pe($row['created_at']))?></span></td><td><?=e($row['client_name'])?> → <?=e($row['provider_name'])?></td><td><?=(int)$row['rating']?>/5</td><td><?=e(mb_strimwidth((string)($row['comment']??'Sin comentario'),0,120,'…'))?></td><td><span class="status status-<?=e(status_class($row['status']))?>"><?=e(status_label($row['status']))?></span></td><td><form class="table-actions" action="<?=e(url('actions.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="admin_review_status"><input type="hidden" name="review_id" value="<?=(int)$row['id']?>"><button class="btn btn-primary btn-small" name="status" value="published">Publicar</button><button class="btn btn-ghost btn-small" name="status" value="hidden">Ocultar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require dirname(__DIR__).'/templates/dashboard-footer.php';?>
